CREATE Proc [dbo].[ReportVendorWiseReceivingReport] @From as datetime, @To as Datetime,  @Login as nvarchar(max), @VendorId as text, @SId as int as Declare @ReportName as nvarchar(max);  set @ReportName='GOODS RECEIVING STORE SUBCATEGORY WISE'; select CONVERT(VARCHAR(11),@From,106) as [From], CONVERT(VARCHAR(11),@To,106) as [To], gm.RefrenceNo as LoginUser,gm.Date,gm.GRNo,v.Vendor,@ReportName as store,c.Category,sc.Subcategory,i.Item, (Select Unit from unit  where UId=gd.PackageId) as PackingType,gd.TotalPackage,gd.PcsPerPackage,  '' as DSNo, gm.Discount,(select PONo from PurchaseOrderMaster_Store where POId = gd.POId) as PONo,Un.Unit as IssuanceType,iu.IssFactor,iu.PurFactor,Uni.Unit as ReceipeType,iu.RecpFactor,UT.Unit as PurchaseUnit,iu.PkFactor,(Select Distinct(Unit) from unit  where UId=gd.Unit) as UnitType,(select ParLevel from ItemParLevel where ItemId= i.ItemId and SId = @SId) as ParLevel,isnull((select sum(Qty) from PurchaseOrderDetail_Store where ItemId = i.ItemId and POId = gd.POId),0) as OrderQty,gd.Rate as UnitPrice,gd.Qty as ReceivedQty from GRNMaster gm inner join GRNDetail gd on gm.GRNId=gd.GRNId inner join Vendor v on v.VId=gm.VId inner join Store s on gm.SId=s.SId inner join Item i on gd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit Un on iu.IssUnit=Un.UId inner join Unit Uni on iu.RecpUnit=Uni.UId inner join Unit UT on iu.PurUnit=UT.UId inner join Split(@VendorId,',') sp on sp.items = v.VId where gm.Date between @From and @To   and gm.SId=@SId and i.ItemId=gd.ItemId group by gm.Date,gm.GRNo,v.Vendor,c.Category,sc.Subcategory,i.Item, gd.PackageId,gd.TotalPackage,gd.PcsPerPackage, UT.Unit, gm.Discount, v.Address,v.CellNo, iu.IssFactor,iu.PurFactor, iu.RecpFactor,iu.PkFactor,gd.Unit,Un.Unit,Uni.Unit,i.ItemCode,gm.RefrenceNo ,gd.Qty,gd.Rate,gm.BRId,i.ItemId,gm.SId,gd.POId order by gm.date,i.ItemId asc